 92  /**
 93   * 没挂上、没开工的说明，给 /api/health 的 problems。基地换版靠它判断新版能不能用。
 94   * @param status 这次启动实际尝试挂过的插件。
 95   * @returns 不是 ok 的插件各一句；全开工了是空数组。
 96   */
 97  export function getPluginProblems(status: PluginStatus[]): string[] {
 98    const problems: string[] = [];
 99    for (const item of status) {
100      //M 开工了的不算问题。
101      if (item.state === 'ok') continue;
102
103      //M 等服务的叫没开工，还在起、失败的叫没挂上；有说明就带上。
104      let problem = `插件 ${item.name} 没挂上`;
105      if (item.state === 'waiting') {
106        problem = `插件 ${item.name} 没开工`;
107      }
108      if (item.error !== '') {
109        problem += `：${item.error}`;
110      }
111      problems.push(problem);
112    }
113    return problems;
114  }
115
116
