162  /** 从磁盘读取并校验配置，错误信息不含 YAML 原文。 */
163  function readConfig(file: string): ConfigSnapshot {
164    //M 启动和重读共用同一份入口校验。
165    const yamlText = fs.readFileSync(file, 'utf8');
166    const document = yaml.parseDocument(yamlText);
167  
168    //G YAML 解析错误会带出原文，错误里只保留行号。
169    const broken = document.errors[0];
170    if (broken !== undefined) {
171      const line = String(broken.linePos?.[0].line ?? '?');
172      throw new Error(`config.yaml 不是合法的 YAML（第 ${line} 行附近）`);
173    }
174  
175    const written: unknown = document.toJSON();
176    //M 交给 checkConfig 校验一次。顶层确认是对象后，插件仍可读取原始值。
177    const config = checks.checkConfig(written);
178    const raw = written as Record<string, unknown>;
179    return { config, raw };
180  }
181  
182  
```

### 解释
- L165：读 config.yaml 原文。
- L169–L173：守卫：YAML 解析错误会带出原文，错误里只保留行号。
- L177：**外部入口**：交给 checkConfig 校验一次，之后内部直接用。
- L179：校验后的配置和原始对象一起交回。

