299    /** 监听 config.yaml，合并保存动作产生的多次文件通知。 */
300    private watchConfig(file: string): void {
301      this.ctx.effect(() => {
302        let pending: ReturnType<typeof setTimeout> | undefined;
303        //M 非持久监听与定时器让命令行模式能照常退出。
304        const watcher = fs.watch(this.root, { persistent: false }, (_event, name) => {
305          if (name !== null && name.toLowerCase() !== CONFIG_FILE) return;
306  
307          clearTimeout(pending);
308          pending = setTimeout(() => this.reloadConfig(file), CONFIG_RELOAD_DELAY_MS);
309          pending.unref();
310        });
311        watcher.on('error', (error) => {
312          console.error(`config.yaml 监听失败：${error.message}`);
313        });
314        return () => {
315          clearTimeout(pending);
316          watcher.close();
317        };
318      });
319    }
320  
```

### 解释
- L304：监听父目录（设置页用临时文件原子替换后仍能继续监听）；非持久监听让命令行模式能照常退出。
