321    /** 校验并应用新快照，失败时继续使用原配置。 */
322    private reloadConfig(file: string): void {
323      try {
324        const next = readConfig(file);
325        //G 一次保存可能产生多次文件通知，内容相同就沿用当前快照。
326        if (util.isDeepStrictEqual(this.raw, next.raw)) return;
327  
328        //M 先更新 pi 的供应商，再让下次读取拿到新快照。
329        this.updateProviders(next.config.providers, this.config.providers);
330        this.current = next;
331      } catch (error) {
332        const reason = textModule.getErrorMessage(error);
333        console.error(`config.yaml 重读失败，继续使用原配置：${reason}`);
334      }
335    }
336  
```

